@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('modern-invoice-form'),date=document.getElementById('invoice-pricing-date'),token=form.querySelector('[name="_token"]').value;const update=async()=>{let cents=0,unavailable=false;for(const select of document.querySelectorAll('.tariff-select')){const fee=select.dataset.fee,opt=select.selectedOptions[0],card=select.closest('.card-body'),checked=card.querySelector('.fee-check').checked;const names={gradeGroup:'grade_group',paymentPeriod:'payment_period',size:'uniform_size',item:'uniform_item',optionType:'option_type',optionValue:'option_value'};Object.keys(names).forEach(key=>card.querySelector(`[name="${names[key]}[${fee}]"]`).value=opt.dataset[key]||'');if(!checked)continue;const body=new FormData();body.append('_token',token);body.append('fee_id',fee);body.append('quantity','1');body.append('academic_year_id','{{ $year->id }}');body.append('grade_id','{{ $student->currentEnrollment?->grade_id }}');body.append('enrollment_mode_id','{{ $student->currentEnrollment?->enrollment_mode_id }}');body.append('registration_date',date.value);Object.keys(names).forEach(key=>{if(opt.dataset[key])body.append(names[key]==='uniform_size'?'size':names[key]==='uniform_item'?'item':names[key],opt.dataset[key]);});const response=await fetch('{{ route('dashboard.quick-registration.price') }}',{method:'POST',body,headers:{Accept:'application/json'}});if(!response.ok){card.querySelector('.price-preview').textContent='Тариф не настроен.';card.querySelector('.tariff-validity').textContent='На выбранную дату тариф не настроен.';unavailable=true;continue;}const result=await response.json();cents+=Math.round(Number(result.amount)*100);card.querySelector('.price-preview').textContent=Number(result.amount).toFixed(2)+' EGP';const format=value=>value?new Date(`${value}T00:00:00`).toLocaleDateString('ru-RU'):'';card.querySelector('.tariff-validity').textContent=result.valid_from?`Действует с ${format(result.valid_from)}${result.valid_to?` по ${format(result.valid_to)}`:''}`:'';}document.getElementById('invoice-preview-total').textContent=(cents/100).toFixed(2)+' EGP';form.dataset.pricingAvailable=unavailable?'false':'true';};document.querySelectorAll('.fee-check,.tariff-select').forEach(el=>el.addEventListener('change',update));date.addEventListener('change',update);form.addEventListener('submit',event=>{if(form.dataset.pricingAvailable==='false')event.preventDefault();});update();});</script>@endpush
